"""SQLAlchemy 2.0 database models for User Generated Roadmaps and Daily Learning Activities."""

from datetime import datetime
from typing import TYPE_CHECKING
import uuid

from sqlalchemy import Boolean, DateTime, ForeignKey, Integer, String, UniqueConstraint, JSON, func
from sqlalchemy.dialects.postgresql import UUID
from sqlalchemy.orm import Mapped, mapped_column, relationship

from app.db.base import Base

if TYPE_CHECKING:
    from app.models.user import User


class UserGeneratedRoadmap(Base):
    """Stores user-described custom career roadmaps generated by AI Roadmap Builder."""

    __tablename__ = "user_generated_roadmaps"

    id: Mapped[int] = mapped_column(
        Integer,
        primary_key=True,
        autoincrement=True,
        index=True,
        nullable=False,
    )
    user_id: Mapped[uuid.UUID | None] = mapped_column(
        UUID(as_uuid=True),
        ForeignKey("users.id", ondelete="CASCADE"),
        nullable=True,
        index=True,
    )
    goal: Mapped[str] = mapped_column(
        String(500),
        nullable=False,
    )
    title: Mapped[str] = mapped_column(
        String(255),
        nullable=False,
    )
    target_role: Mapped[str | None] = mapped_column(
        String(100),
        nullable=True,
    )
    experience_level: Mapped[str] = mapped_column(
        String(50),
        default="Beginner",
        nullable=False,
    )
    estimated_duration: Mapped[str | None] = mapped_column(
        String(100),
        nullable=True,
    )
    roadmap_data: Mapped[dict] = mapped_column(
        JSON,
        nullable=False,
        default=dict,
    )
    is_active: Mapped[bool] = mapped_column(
        Boolean,
        default=True,
        nullable=False,
    )
    progress_percent: Mapped[int] = mapped_column(
        Integer,
        default=0,
        nullable=False,
    )
    completed_milestone_ids: Mapped[list[int | str] | None] = mapped_column(
        JSON,
        default=list,
        nullable=True,
    )
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        server_default=func.now(),
        nullable=False,
    )
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        server_default=func.now(),
        onupdate=func.now(),
        nullable=False,
    )

    user: Mapped["User | None"] = relationship(
        "User",
        foreign_keys=[user_id],
        back_populates="generated_roadmaps",
    )

    def __repr__(self) -> str:
        return f"<UserGeneratedRoadmap(id={self.id}, user_id={self.user_id}, title='{self.title}')>"


class DailyLearningActivity(Base):
    """Tracks daily productivity checklist, streak, and time spent."""

    __tablename__ = "daily_learning_activity"
    __table_args__ = (
        UniqueConstraint("user_id", "activity_date", name="uq_user_daily_activity"),
    )

    id: Mapped[int] = mapped_column(
        Integer,
        primary_key=True,
        autoincrement=True,
        index=True,
        nullable=False,
    )
    user_id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True),
        ForeignKey("users.id", ondelete="CASCADE"),
        nullable=False,
        index=True,
    )
    activity_date: Mapped[str] = mapped_column(
        String(10),
        index=True,
        nullable=False,
    )  # ISO format "YYYY-MM-DD"
    completed_tasks: Mapped[list[str]] = mapped_column(
        JSON,
        default=list,
        nullable=False,
    )  # e.g. ["lesson", "milestone", "practice"]
    task_count: Mapped[int] = mapped_column(
        Integer,
        default=0,
        nullable=False,
    )
    streak_count: Mapped[int] = mapped_column(
        Integer,
        default=1,
        nullable=False,
    )
    minutes_spent: Mapped[int] = mapped_column(
        Integer,
        default=0,
        nullable=False,
    )
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        server_default=func.now(),
        nullable=False,
    )
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        server_default=func.now(),
        onupdate=func.now(),
        nullable=False,
    )

    user: Mapped["User"] = relationship(
        "User",
        foreign_keys=[user_id],
        back_populates="daily_activities",
    )

    def __repr__(self) -> str:
        return f"<DailyLearningActivity(user_id={self.user_id}, date='{self.activity_date}', streak={self.streak_count})>"
